import{_ as a,o as s,c as e,ai as i}from"./chunks/framework.BxxKhjs3.js";const h=JSON.parse('{"title":"05-变量","description":"","frontmatter":{},"headers":[],"relativePath":"仓颉入门到实战/05-变量/05-变量.md","filePath":"仓颉入门到实战/05-变量/05-变量.md","lastUpdated":1734110581000,"__rawMarkdown":"# 05-变量\\n\\n## 什么是变量\\n\\n在计算机编程的复杂体系中，变量可被精准地定义为计算机内存里专门用于存储数据的特定空间区域。当我们着手进行程序设计时，无论\\n\\n是开发一款功能精巧的闹钟应用，还是构建一个便捷高效的购物车系统，变量都扮演着不可或缺的角色。在闹钟程序里，为了精确记录和\\n\\n显示时间信息，需要相应的变量来存储时间数据，这些数据会随着时间的推移而不断更新，从而确保闹钟能够准确地执行其定时提醒功\\n\\n能。同样地，在购物车程序中，变量则用于存储各类购物数据，包括商品的名称、数量、价格等详细信息，这些数据的动态变化反映了用\\n\\n户的购物行为和购物车的实时状态，是实现购物车功能的基础支撑。\\n\\n## 变量的特点\\n\\n在仓颉语言中，变量具备以下特点：\\n\\n1. 变量的名称需要是一个合法的标记符\\n2. 变量也有类型，如数字、文本等类型。\\n3. 变量在使用时，需要初始化/赋值。也就是程序不能访问一块闲置的内存\\n4. 变量分为可变和不可变。\\n\\n\\n\\n## 变量的名称需要是一个合法的标记符\\n\\n**正例**\\n\\n```\\n// 创建一个变量  文本类型 => 字符串类型\\nlet userName = \\"小万\\" // 变量名称为  userName  存储的内容是 \\"小万\\"\\n```\\n\\n**反例**\\n\\n```\\nlet 123userName = \\"小万\\" //  不能以数字开头\\n```\\n\\n## 变量也有类型，如数字、文本等类型\\n\\n **正例**\\n\\n```\\n// 创建一个变量  数字类型\\nlet num = 100 // 变量名称为 num 存储的内容是 数字 100 \\n```\\n\\n\\n\\n## 变量在使用时，需要初始化/赋值\\n\\n也就是程序不能访问一块闲置的内存\\n\\n**正例**\\n\\n```\\n// 先创建 再使用\\nlet age = 300 // 创建变量\\nprint(age) // 使用变量\\n```\\n\\n**反例**\\n\\n```\\nprint(address) // address 从来没有声明过\\n```\\n\\n## 变量分为可变和不可变\\n\\n1. 不可变的变量需要使用关键字 **let**\\n2. 可变的变量需要使用关键字 **var**\\n\\n\\n\\n**正例**\\n\\n```\\nvar age = 20\\nage = 30 // 可变 \\n```\\n\\n**反例**\\n\\n```\\nlet age = 20\\nage = 30 // 不可变 \\n```\\n\\n"}'),p={name:"仓颉入门到实战/05-变量/05-变量.md"};function t(l,n,r,d,o,c){return s(),e("div",null,[...n[0]||(n[0]=[i("",30)])])}const b=a(p,[["render",t]]);export{h as __pageData,b as default};
